using ModelContextProtocol;
using ModelContextProtocol.Server;
using System.ComponentModel;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddMcpServer()
    .WithHttpTransport()
    .WithToolsFromAssembly()
    .WithResources();

var app = builder.Build();

// Map MCP endpoint at /mcp (handles Streamable HTTP transport)
app.MapMcp();

app.Run();

// --- Tool definitions ---

[McpServerToolType]
public static class EchoTool
{
    [McpServerTool, Description("Echoes the input message back to the caller.")]
    public static string Echo(string message) => $"Echo: {message}";
}

[McpServerToolType]
public static class MathTool
{
    [McpServerTool, Description("Adds two numbers together.")]
    public static double Add(double a, double b) => a + b;
}

// --- Resource definitions ---

[McpServerResourceType]
public static class ConfigResource
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Configuration",
        Description = "Returns the current application configuration data.")]
    public static string GetAppConfig()
    {
        var config = new
        {
            AppName = "McpHttpServer",
            Version = "1.0.0",
            Environment = "Production",
            MaxConnections = 100,
            Features = new[] { "tools", "resources", "http-transport" }
        };
        return System.Text.Json.JsonSerializer.Serialize(config,
            new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }

    [McpServerResource(
        UriTemplate = "config://status",
        Name = "Server Status",
        Description = "Returns the current server status.")]
    public static string GetServerStatus()
    {
        return System.Text.Json.JsonSerializer.Serialize(new
        {
            Status = "healthy",
            Uptime = Environment.TickCount64 / 1000,
            Timestamp = DateTime.UtcNow
        }, new System.Text.Json.JsonSerializerOptions { WriteIndented = true });
    }
}

